CREATE OR REPLACE FUNCTION private.account_access_allowed() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.account_restrictions WHERE user_id=auth.uid() AND banned_until>now()) AND NOT EXISTS(SELECT 1 FROM public.viewer_sessions WHERE session_id::text=auth.jwt()->>'session_id' AND revoked_at IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM public.security_blocks WHERE kind='email' AND value=lower(auth.jwt()->>'email')) AND NOT EXISTS(SELECT 1 FROM public.viewer_sessions s JOIN public.security_blocks b ON (b.kind='fingerprint' AND b.value=s.device_hash) OR (b.kind='ip' AND b.value=s.ip) WHERE s.session_id::text=auth.jwt()->>'session_id'); $$;
REVOKE ALL ON FUNCTION private.account_access_allowed() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION private.account_access_allowed() TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.record_viewer_presence_internal(p_user uuid,p_session uuid,p_device text,p_name text,p_ip text,p_country text,p_city text,p_agent text,p_touch jsonb,p_state text,p_episode uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE previous public.viewer_sessions; elapsed numeric:=0; gap numeric; BEGIN
 IF p_state NOT IN ('active','idle','watching') THEN RAISE EXCEPTION 'Invalid presence'; END IF;
 INSERT INTO public.viewer_sessions(session_id,user_id,device_hash,device_name,ip,country,city,user_agent,first_touch,last_touch,state,current_episode_id) VALUES(p_session,p_user,p_device,p_name,nullif(p_ip,''),nullif(p_country,''),nullif(p_city,''),p_agent,p_touch,p_touch,p_state,p_episode) ON CONFLICT(session_id) DO NOTHING;
 SELECT * INTO previous FROM public.viewer_sessions WHERE session_id=p_session FOR UPDATE;
 IF previous.user_id<>p_user OR previous.revoked_at IS NOT NULL THEN RAISE EXCEPTION 'Session unavailable'; END IF;
 gap:=extract(epoch FROM now()-previous.last_seen_at);
 IF previous.state='watching' AND previous.current_episode_id IS NOT NULL AND gap<=45 THEN elapsed:=greatest(0,least(30,gap)); INSERT INTO public.viewer_watch_history(user_id,session_id,episode_id,watched_seconds) VALUES(p_user,p_session,previous.current_episode_id,elapsed) ON CONFLICT(session_id,episode_id) DO UPDATE SET watched_seconds=viewer_watch_history.watched_seconds+elapsed,last_watched_at=now(); END IF;
 UPDATE public.viewer_sessions SET device_hash=p_device,device_name=p_name,ip=nullif(p_ip,''),country=nullif(p_country,''),city=nullif(p_city,''),user_agent=p_agent,last_touch=p_touch,state=p_state,current_episode_id=p_episode,watched_seconds=watched_seconds+elapsed,last_seen_at=now() WHERE session_id=p_session;
 END; $$;
REVOKE ALL ON FUNCTION public.record_viewer_presence_internal(uuid,uuid,text,text,text,text,text,text,jsonb,text,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.record_viewer_presence_internal(uuid,uuid,text,text,text,text,text,text,jsonb,text,uuid) TO service_role;